"use client";

import type { EventCourseCollection, EventPlatformSettings } from "@/packages/contracts/src";
import type { Athlete, RaceEvent } from "@/lib/types";
import type { FeibotAccountCredentialStatus, FeibotAdminConnection, FeibotOperationName, FeibotOperationsDashboard } from "@/lib/feibot-integration";
import type { LiveTrackingHubConfig } from "@/lib/live-tracking-hub-config";
import type { FinisherNotificationChannel, FinisherTraceRow, ResultEmailSummary } from "@/lib/result-emails";
import type { CanonicalAdminSnapshot } from "@/lib/canonical-live-tracking";
import { formatCutoffDuration, parseCutoffDuration } from "@/lib/cutoff-duration";
import { normalizeRaceFlowPassages, raceFlowIssues, reorderContestSplits } from "@/lib/race-flow-editor";
import { expandFeibotSportLegs, normalizeHubRaceFlowConfig } from "@/lib/race-flow-legs";
import { AlertTriangle, Check, ChevronDown, ChevronRight, Circle, Copy, Database, Download, Eye, EyeOff, GripVertical, KeyRound, Loader2, Mail, MessageCircle, Play, Plus, RefreshCw, Route, Save, Search, Send, ShieldCheck, Trash2, UploadCloud, X, XCircle } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { CourseMapsAdmin } from "./course-maps-admin";
import { LiveTrackingLogsPanel } from "./live-tracking-logs-panel";
import { PublishResults } from "./publish-results";

type HubEvent = RaceEvent & { feibot: FeibotAdminConnection; config: LiveTrackingHubConfig; courseMaps: EventCourseCollection; results: Athlete[]; settings: EventPlatformSettings; operations: FeibotOperationsDashboard };
const tabs = [["setup","Event Configuration"],["contest","Contest Mapping"],["start","Start Configuration"],["flow","Leg & Split Mapping"],["points","Timing Points"],["maps","Course Maps"],["sync","Feibot Sync"],["logs","Logs"],["notifications","Notifications"],["export","Export Results"],["reset","Reset Data"],["upload","Upload Results"]] as const;
type Tab = typeof tabs[number][0];
const operations: Array<[FeibotOperationName,string,string]> = [
  ["IMPORT_TIMING_RULES","Import Timing Rules","Download and normalize provider contests, legs, splits and timing points."],
  ["REBUILD_SPLIT_INDEX","Rebuild Split Index","Generate and verify split, leg and timing-point lookup indexes."],
  ["VALIDATE_KV","Validate KV","Inspect provider, configuration, split index and canonical readiness."],
  ["REFRESH_STATUS","Refresh Provider Status","Refresh secure backend state and counts."],
  ["TEST_TIMING_RULES","Test Timing Rules API","Call timingRulesGet and show a redacted response."],
  ["TEST_PARTICIPANTS","Test Participants API","Call participantsGetAll and show a redacted response."],
  ["FETCH_FEIBOT_READS","Fetch Feibot Reads","Fetch event-scoped processed timing reads from Feibot."],
  ["FETCH_FEIBOT_RESULTS","Fetch Feibot Result","Fetch the current event-scoped temporary results and publish an incremental projection."],
  ["FULL_REBUILD","Full Rebuild","Import, index, synchronize and publish a complete canonical version."],
  ["HARD_RESET_SYNC","Hard Reset + Fresh Cloud Sync","Remove imported projections and immediately rebuild from Feibot."],
  ["DELETE_IMPORTED_DATA","Delete All Feibot Imported Data","Remove imported keys while preserving credentials, mappings, maps and canonical versions."],
];
const local = (value: string | null) => value?.slice(0,16) ?? "";
const toIso = (value: string) => value ? new Date(value).toISOString() : null;
const uid = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const xml = (value: unknown) => String(value ?? "").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
const exportColumns = [["bib","Bib Number"],["name","Name"],["email","E-mail"],["category","Category"],["gender","Gender"],["ageGroup","Age Group"],["club","Club"],["rank","Overall Rank"],["genderRank","Gender Rank"],["ageRank","Age Group Rank"],["finishTime","Finish Time"],["status","Status"]] as const;

function CutoffDurationInput({ value, disabled = false, onChange }: { value: number | null | undefined; disabled?: boolean; onChange: (seconds: number | null) => void }) {
  const [invalid,setInvalid]=useState(false);
  return <span className="hub-cutoff-input"><input key={String(value)} type="text" inputMode="numeric" autoComplete="off" placeholder="HH:MM:SS" aria-label="Cutoff time in hours minutes seconds" aria-invalid={invalid} disabled={disabled} defaultValue={formatCutoffDuration(value)} onChange={()=>setInvalid(false)} onBlur={event=>{const raw=event.currentTarget.value.trim();if(!raw){onChange(null);setInvalid(false);return;}const parsed=parseCutoffDuration(raw);if(parsed==null){setInvalid(true);return;}event.currentTarget.value=formatCutoffDuration(parsed);setInvalid(false);onChange(parsed);}} />{invalid?<small role="alert">Enter HH:MM or HH:MM:SS, for example 01:30:00.</small>:null}</span>;
}

export function LiveTrackingHub({ events, initialAccountCredentials, loadWarning = "" }: { events: HubEvent[]; initialAccountCredentials: FeibotAccountCredentialStatus; loadWarning?: string }) {
  const [eventId,setEventId] = useState(events[0]?.id ?? "");
  const [tab,setTab] = useState<Tab>("setup");
  const [configs,setConfigs] = useState(() => Object.fromEntries(events.map(e => [e.id,normalizeHubRaceFlowConfig(e.config)])) as Record<string,LiveTrackingHubConfig>);
  const [connections,setConnections] = useState(() => Object.fromEntries(events.map(e => [e.id,e.feibot])) as Record<string,FeibotAdminConnection>);
  const [dashboards,setDashboards] = useState(() => Object.fromEntries(events.map(e => [e.id,e.operations])) as Record<string,FeibotOperationsDashboard>);
  const [platforms,setPlatforms] = useState(() => Object.fromEntries(events.map(e => [e.id,e.settings])) as Record<string,EventPlatformSettings>);
  const [courseMaps,setCourseMaps] = useState(() => Object.fromEntries(events.map(e => [e.id,e.courseMaps])) as Record<string,EventCourseCollection>);
  const [credentials,setCredentials] = useState({accessKey:"",secretKey:"",eventUuid:"",baseUrl:"https://apicn.feibot.com"});
  const [connectionLabel,setConnectionLabel] = useState("");
  const [editingConnectionId,setEditingConnectionId] = useState<string|null>(null);
  const [connectionFormOpen,setConnectionFormOpen] = useState(!events[0]?.feibot.connections.length);
  const [accountCredentials,setAccountCredentials] = useState(initialAccountCredentials);
  const [accountForm,setAccountForm] = useState({accountId:initialAccountCredentials.accountId,accessKey:"",secretKey:"",baseUrl:initialAccountCredentials.baseUrl});
  const [busy,setBusy] = useState(""); const [message,setMessage] = useState(""); const [error,setError] = useState(""); const [output,setOutput] = useState("");
  const [canonicalSnapshot,setCanonicalSnapshot] = useState<CanonicalAdminSnapshot|null>(null);
  const [canonicalOpen,setCanonicalOpen] = useState(false);
  const [canonicalBusy,setCanonicalBusy] = useState(false);
  const [exportFields,setExportFields] = useState<Set<string>>(() => new Set(exportColumns.map(([key])=>key)));
  const [notificationCategory,setNotificationCategory] = useState("Overall");
  const [notificationSummary,setNotificationSummary] = useState<ResultEmailSummary|null>(null);
  const [notificationSummaries,setNotificationSummaries] = useState<Record<string,ResultEmailSummary>>({});
  const event = useMemo(() => events.find(e => e.id === eventId) ?? events[0],[eventId,events]);
  const config = event && configs[event.id]; const connection = event && connections[event.id]; const dashboard = event && dashboards[event.id]; const platform = event && platforms[event.id];
  const update = (next: LiveTrackingHubConfig) => event && setConfigs(all => ({...all,[event.id]:next}));
  const clear = () => { setMessage(""); setError(""); };

  async function reload(id: string) { const r=await fetch(`/api/v1/admin/events/${encodeURIComponent(id)}/live-tracking-hub`,{cache:"no-store"}); const p=await r.json() as {ok?:boolean;data?:LiveTrackingHubConfig}; if(r.ok&&p.ok&&p.data)setConfigs(a=>({...a,[id]:normalizeHubRaceFlowConfig(p.data!)})); }
  async function refreshDashboard() { if(!event)return;const r=await fetch(`/api/v1/admin/events/${encodeURIComponent(event.id)}/feibot-operations`,{cache:"no-store"});const p=await r.json() as {success?:boolean;data?:FeibotOperationsDashboard;error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Unable to refresh live tracking data.");setDashboards(a=>({...a,[event.id]:p.data!}));setConnections(a=>({...a,[event.id]:p.data!.connection}));return p.data;}
  async function save() { if(!event||!config)return; setBusy("save");clear(); try { const {eventId:_,updatedAt:__,...body}=config; void _;void __; const r=await fetch(`/api/v1/admin/events/${event.id}/live-tracking-hub`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(body)}); const p=await r.json() as {ok?:boolean;data?:LiveTrackingHubConfig;error?:string}; if(!r.ok||!p.ok||!p.data)throw new Error(p.error||"Unable to save configuration."); update(p.data);setMessage("Configuration saved to event-scoped RACEUPSHOT KV."); } catch(e){setError(e instanceof Error?e.message:"Save failed.");} finally{setBusy("");} }
  async function connect(refresh=false, source?:"EVENT"|"ACCOUNT") { if(!event)return;setBusy("connect");clear();try{const selectedSource=source??connection?.credentialSource??"EVENT";const body=refresh?{connectionId:editingConnectionId||connection?.connectionId}:{...credentials,label:connectionLabel,connectionId:editingConnectionId||undefined,credentialSource:selectedSource,...(selectedSource==="ACCOUNT"?{accessKey:"",secretKey:""}:{})};const r=await fetch(`/api/v1/admin/events/${event.id}/feibot`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const p=await r.json() as {success?:boolean;data?:FeibotAdminConnection;error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Connection failed.");setConnections(a=>({...a,[event.id]:p.data!}));setCredentials({accessKey:"",secretKey:"",eventUuid:p.data.eventUuid,baseUrl:p.data.baseUrl});setConnectionLabel(p.data.label||"");setEditingConnectionId(p.data.connectionId);setConnectionFormOpen(false);await run("REFRESH_STATUS",true);setMessage(refresh?"Selected Feibot connection refreshed and canonical data rebuilt.":`${p.data.credentialSource==="ACCOUNT"?"Account":"Event"} credentials verified and linked.`);}catch(e){setError(e instanceof Error?e.message:"Connection failed.");}finally{setBusy("");}}
  async function accountAction(action:"save"|"test"|"delete"){if(!event)return;if(action==="delete"&&!confirm("Delete the Feibot account key? Event mappings and canonical data will remain, but account-linked events will disconnect."))return;setBusy(`account-${action}`);clear();try{const r=await fetch("/api/v1/admin/feibot-account",action==="delete"?{method:"DELETE"}:{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(action==="save"?{action,...accountForm}:{action,eventUuid:credentials.eventUuid||connection?.eventUuid})});const p=await r.json() as {success?:boolean;data?:FeibotAccountCredentialStatus;error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Account credential action failed.");setAccountCredentials(p.data);setAccountForm(a=>({...a,accountId:p.data!.accountId,accessKey:"",secretKey:"",baseUrl:p.data!.baseUrl}));setMessage(action==="save"?"Account credentials saved securely on the backend.":action==="test"?"Account credentials verified for the selected Feibot event.":"Account credentials deleted; event mappings and canonical data were preserved.");}catch(e){setError(e instanceof Error?e.message:"Account credential action failed.");}finally{setBusy("");}}
  async function disconnect(connectionId?:string|null){if(!event||!connectionId||!confirm("Delete only this Feibot connection? Its sibling connections, mappings, maps and canonical history will remain."))return;setBusy("disconnect");clear();try{const r=await fetch(`/api/v1/admin/events/${event.id}/feibot?connectionId=${encodeURIComponent(connectionId)}`,{method:"DELETE"});const p=await r.json() as {success?:boolean;data?:FeibotAdminConnection;error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Unable to remove connection.");setConnections(a=>({...a,[event.id]:p.data!}));setConnectionFormOpen(!p.data.connections.length);setEditingConnectionId(null);setCredentials({accessKey:"",secretKey:"",eventUuid:"",baseUrl:"https://apicn.feibot.com"});void refreshDashboard().catch(()=>undefined);setMessage("Selected Feibot connection removed; sibling connections and protected configuration were preserved.");}catch(e){setError(e instanceof Error?e.message:"Disconnect failed.");}finally{setBusy("");}}
  async function verifyConnection(connectionId?:string|null){if(!event)return;setBusy("verify");clear();try{const r=await fetch(`/api/v1/admin/events/${event.id}/feibot`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({connectionId:connectionId||connection?.connectionId})});const p=await r.json() as {success?:boolean;data?:FeibotAdminConnection;error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Connection verification failed.");setConnections(a=>({...a,[event.id]:p.data!}));setEditingConnectionId(p.data.connectionId);setConnectionLabel(p.data.label||"");setCredentials({accessKey:"",secretKey:"",eventUuid:p.data.eventUuid,baseUrl:p.data.baseUrl});void refreshDashboard().catch(()=>undefined);setMessage(`Verified ${p.data.credentialSource==="ACCOUNT"?"Account":"Event"} Key for ${p.data.label||p.data.eventName||event.name}.`);}catch(e){setError(e instanceof Error?e.message:"Connection verification failed.");}finally{setBusy("");}}
  function addConnection(){setEditingConnectionId(null);setConnectionLabel("");setCredentials({accessKey:"",secretKey:"",eventUuid:"",baseUrl:"https://apicn.feibot.com"});setConnectionFormOpen(true);clear();}
  function manageConnection(card:FeibotAdminConnection["connections"][number]){setEditingConnectionId(card.connectionId);setConnectionLabel(card.label);setCredentials({accessKey:"",secretKey:"",eventUuid:card.eventUuid,baseUrl:"https://apicn.feibot.com"});setConnectionFormOpen(true);void verifyConnection(card.connectionId);}
  async function run(action:FeibotOperationName,quiet=false){if(!event)return;if((action==="HARD_RESET_SYNC"||action==="DELETE_IMPORTED_DATA")&&!confirm(`${action.replaceAll("_"," ")} for ${event.name}? Protected configuration is preserved.`))return;setBusy(action);if(!quiet)clear();try{const r=await fetch(`/api/v1/admin/events/${event.id}/feibot-operations`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action})});const p=await r.json() as {success?:boolean;data?:{data:unknown;dashboard:FeibotOperationsDashboard};error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.success||!p.data)throw new Error(reason||"Operation failed.");setDashboards(a=>({...a,[event.id]:p.data!.dashboard}));setConnections(a=>({...a,[event.id]:p.data!.dashboard.connection}));setOutput(JSON.stringify(p.data.data,null,2));await reload(event.id);if(!quiet)setMessage(`${operations.find(x=>x[0]===action)?.[1]??action} completed.`);}catch(e){setError(e instanceof Error?e.message:"Operation failed.");}finally{setBusy("");}}
  async function setPublic(enabled:boolean){if(!event||!platform||(enabled&&!dashboard?.ready))return;setBusy("public");clear();try{const next={...platform,live:{...platform.live,liveTrackingEnabled:enabled,publicLiveTrackingEnabled:enabled}};const r=await fetch(`/api/v1/admin/events/${event.id}/settings`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify(next)});const p=await r.json() as {success?:boolean;data?:EventPlatformSettings};if(!r.ok||!p.success||!p.data)throw new Error("Unable to change tracking visibility.");setPlatforms(a=>({...a,[event.id]:p.data!}));setMessage(`Public live tracking ${enabled?"enabled":"disabled"}.`);}catch(e){setError(e instanceof Error?e.message:"Update failed.");}finally{setBusy("");}}
  async function loadCanonical(open=true){if(!event)return;setCanonicalBusy(true);clear();try{const r=await fetch(`/api/v1/admin/events/${encodeURIComponent(event.id)}/canonical?detail=1`,{cache:"no-store"});const p=await r.json() as {success?:boolean;data?:CanonicalAdminSnapshot;error?:{message?:string}};if(!r.ok||!p.success||!p.data)throw new Error(p.error?.message||"Unable to inspect canonical KV.");setCanonicalSnapshot(p.data);if(open)setCanonicalOpen(true);}catch(e){setError(e instanceof Error?e.message:"Canonical inspection failed.");}finally{setCanonicalBusy(false);}}
  async function rebuildCanonical(){if(!event)return;await run("FULL_REBUILD");await loadCanonical(false);}
  async function reset(){if(!event||!confirm(`Reset generated live timing for ${event.name}? Feibot setup, mappings, course, provider roster, raw reads and chip audit history will be preserved.`))return;setBusy("reset");clear();try{const r=await fetch(`/api/v1/admin/events/${event.id}/canonical`,{method:"DELETE"});const p=await r.json() as {success?:boolean;data?:{deleted?:number};error?:{message?:string}};if(!r.ok||!p.success)throw new Error(p.error?.message||"Canonical reset failed.");await refreshDashboard();await loadCanonical(false);setMessage(`${p.data?.deleted??0} generated event-scoped keys reset. Run Full Rebuild before enabling or testing live tracking.`);}catch(e){setError(e instanceof Error?e.message:"Reset failed.");}finally{setBusy("");}}
  async function requestNotificationSummary(targetEvent:HubEvent,category:string,action:"preview"|"send"="preview",channels:FinisherNotificationChannel[]=["EMAIL","WHATSAPP"],retryFailed=false,resultId?:string,forceResend=false,dryRunToken?:string){const r=await fetch(`/api/admin/results/${encodeURIComponent(targetEvent.id)}/notify`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,category,channels,retryFailed,forceResend,confirmed:action==="send",dryRunToken,...(resultId?.trim()?{resultId:resultId.trim()}:{})})});const p=await r.json() as {ok?:boolean;data?:ResultEmailSummary&{dryRun?:{token:string;count:number}};error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.ok||!p.data)throw new Error(reason||"Unable to process notifications.");return p.data;}
  async function refreshNotificationTracing(targetEvent=event){if(!targetEvent)return;setBusy("notify-preview");clear();try{const categories=["Overall",...targetEvent.categories.filter(x=>x!=="Overall")];const r=await fetch(`/api/admin/results/${encodeURIComponent(targetEvent.id)}/notify`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"preview",categories,channels:["EMAIL","WHATSAPP"]})});const p=await r.json() as {ok?:boolean;data?:{summaries?:Record<string,ResultEmailSummary>};error?:string|{message?:string}};const reason=typeof p.error==="string"?p.error:p.error?.message;if(!r.ok||!p.ok||!p.data?.summaries)throw new Error(reason||"Unable to refresh notification tracing.");setNotificationSummaries(p.data.summaries);setNotificationSummary(p.data.summaries.Overall??null);setMessage("Notification tracing refreshed.");}catch(e){setError(e instanceof Error?e.message:"Unable to refresh notification tracing.");}finally{setBusy("");}}
  async function notifyFinishers(action:"preview"|"send",channels:FinisherNotificationChannel[]=["EMAIL","WHATSAPP"],retryFailed=false,selectedCategory=notificationCategory,resultId?:string,forceResend=false){if(!event)return;setBusy(`notify-${action}`);clear();try{const preview=await requestNotificationSummary(event,selectedCategory,"preview",channels,retryFailed,resultId,forceResend);if(action==="send"&&(!preview.dryRun?.count||!confirm(`${forceResend?"Resend":"Send"} ${preview.dryRun.count} channel notification(s) for ${selectedCategory}? Provider acceptance is not confirmed delivery.${forceResend?" This may duplicate earlier accepted messages.":""}`))){setBusy("");return;}const updated=action==="send"?await requestNotificationSummary(event,selectedCategory,"send",channels,retryFailed,resultId,forceResend,preview.dryRun?.token):preview;const overall=selectedCategory==="Overall"?updated:await requestNotificationSummary(event,"Overall");setNotificationSummaries(current=>({...current,[selectedCategory]:updated,Overall:overall}));setNotificationSummary(updated);setNotificationCategory(selectedCategory);setMessage(action==="preview"?"Notification tracing refreshed.":"Batch submitted; provider acceptance state refreshed.");}catch(e){setError(e instanceof Error?e.message:"Notification action failed.");}finally{setBusy("");}}
  function exportExcel(){if(!event)return;const fields=exportColumns.filter(([key])=>exportFields.has(key));const rows=[fields.map(([,label])=>label),...event.results.map(row=>fields.map(([key])=>String((row as unknown as Record<string,unknown>)[key]??"")))];const book=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Live Results"><Table>${rows.map(row=>`<Row>${row.map(cell=>`<Cell><Data ss:Type="String">${xml(cell)}</Data></Cell>`).join("")}</Row>`).join("")}</Table></Worksheet></Workbook>`;const url=URL.createObjectURL(new Blob([book],{type:"application/vnd.ms-excel"}));const a=document.createElement("a");a.href=url;a.download=`${event.slug}-live-results.xls`;a.click();URL.revokeObjectURL(url);}

  if(!event||!config||!connection||!dashboard||!platform)return <section className="admin-card"><div className="admin-empty">Create an event before configuring live tracking.</div></section>;
  const sortedSplits=[...config.splits].sort((a,b)=>a.order-b.order);
  const eventSelector=<div className="live-tracking-event-picker"><label>Race Upshot Event<select value={event.id} onChange={e=>{const next=events.find(x=>x.id===e.target.value);setEventId(e.target.value);setCanonicalSnapshot(null);setCanonicalOpen(false);setOutput("");setNotificationCategory("Overall");setNotificationSummary(null);setNotificationSummaries({});clear();setEditingConnectionId(next?.feibot.connectionId??null);setConnectionLabel(next?.feibot.label??"");setConnectionFormOpen(!next?.feibot.connections.length);setCredentials({accessKey:"",secretKey:"",eventUuid:next?.feibot.eventUuid??"",baseUrl:next?.feibot.baseUrl??"https://apicn.feibot.com"});if(tab==="notifications"&&next)void refreshNotificationTracing(next);}}>{events.map(e=><option key={e.id} value={e.id}>{e.name} · {e.date}</option>)}</select></label><button className="button" type="button" onClick={()=>window.location.reload()}><RefreshCw/> Refresh upcoming events</button><span className="status-pill">{event.status}</span></div>;
  return <div className="live-tracking-hub">
    {loadWarning&&<div className="success-banner cms-error-banner" role="status"><AlertTriangle/> {loadWarning}</div>}
    <section className="live-tracking-hub-hero"><span><ShieldCheck/> Secure Feibot credentials</span><h2>Live Tracking Hub</h2><p>Configure provider connections, timing rules, race flow, public readiness, synchronization and event-scoped canonical data.</p><div><b>{connection.configured?"Credentials stored":"Credentials required"}</b><b>{connection.connected?"Connection verified":"Not connected"}</b></div></section>
    <div className="live-tracking-tabs" role="tablist">{tabs.map(([id,label])=><button key={id} role="tab" aria-selected={tab===id} className={tab===id?"active":""} onClick={()=>{setTab(id);if(id==="reset")void loadCanonical(false);if(id==="notifications")void refreshNotificationTracing();}}>{label}</button>)}</div>
    {tab!=="setup"&&eventSelector}
    {message&&<div className="success-banner"><Check/> {message}</div>}{error&&<div className="success-banner cms-error-banner"><AlertTriangle/> {error}</div>}

    {tab==="setup"&&<div className="bergman-setup-tab">{eventSelector}<ConnectionsSetupPanel event={event} connection={connection} dashboard={dashboard} platform={platform} credentials={credentials} setCredentials={setCredentials} connectionLabel={connectionLabel} setConnectionLabel={setConnectionLabel} connectionFormOpen={connectionFormOpen} editingConnectionId={editingConnectionId} addConnection={addConnection} manageConnection={manageConnection} closeConnectionForm={()=>setConnectionFormOpen(false)} account={accountCredentials} accountForm={accountForm} setAccountForm={setAccountForm} busy={busy} connect={connect} disconnect={disconnect} verifyConnection={verifyConnection} accountAction={accountAction} setPublic={setPublic} refresh={()=>run("REFRESH_STATUS")}/></div>}
    {tab==="contest"&&<section className="admin-card"><div className="admin-card-head"><div><h2>Contest Mapping</h2><p>Map categories only to contests from this selected Feibot UUID.</p></div></div><div className="hub-mapping-list">{event.categories.map(category=><label key={category}><b>{category}</b><select value={config.contestMappings.find(x=>x.contestId===category)?.providerContestUuid??""} onChange={e=>update({...config,contestMappings:[...config.contestMappings.filter(x=>x.contestId!==category),...(e.target.value?[{contestId:category,providerContestUuid:e.target.value}]:[])]})}><option value="">Not mapped</option>{connection.contests.map(c=><option key={c.uuid} value={c.uuid}>{c.name} · {c.uuid}</option>)}</select></label>)}</div><button className="button button-primary" onClick={()=>void save()}><Save/> Save contest mapping</button></section>}
    {tab==="start"&&<StartPanel key={event.id} connection={connection} dashboard={dashboard} config={config} update={update} save={save} refresh={()=>run("IMPORT_TIMING_RULES")} busy={busy}/>}
    {tab==="flow"&&<FlowPanel key={event.id} event={event} connection={connection} dashboard={dashboard} config={config} update={update} save={save} reload={()=>reload(event.id)} importRules={()=>run("IMPORT_TIMING_RULES")} splits={sortedSplits} busy={busy}/>}
    {tab==="points"&&<PointsPanel config={config} update={update} save={save} refresh={()=>run("IMPORT_TIMING_RULES")}/>}
    {tab==="maps"&&<div className="hub-stack"><Provider event={event} connection={connection} dashboard={dashboard}/><CourseMapsAdmin key={event.id} eventId={event.id} eventName={event.name} sport={event.sport} categories={event.categories} initialCollection={courseMaps[event.id] ?? event.courseMaps} splitCounts={{SWIM:config.splits.filter(split=>config.legs.find(leg=>leg.id===split.legId)?.type==="SWIM").length,BIKE:config.splits.filter(split=>config.legs.find(leg=>leg.id===split.legId)?.type==="BIKE").length,RUN:config.splits.filter(split=>config.legs.find(leg=>leg.id===split.legId)?.type==="RUN").length}} onSaved={collection=>setCourseMaps(current=>({...current,[event.id]:collection}))}/></div>}
    {tab==="sync"&&<div className="hub-stack"><Provider event={event} connection={connection} dashboard={dashboard}/><section className="admin-card"><div className="admin-card-head"><div><h2>Canonical Build</h2><p>The complete snapshot consumed by public web and mobile APIs.</p></div><button className="button" disabled={canonicalBusy} onClick={()=>void loadCanonical()}><Database/> View Canonical KV</button></div><Facts rows={[["Manifest",`raceupshot:canonical:event:${event.id}:manifest`],["Active Version",dashboard.manifest?.activeVersion||dashboard.manifest?.version||"None"],["Canonical Validity",dashboard.manifest?.completeBuildValid?"Yes":"No"],["Participants",dashboard.manifest?.participantCount??0],["Participant Version",dashboard.manifest?.participantVersion??"Legacy"],["Built",dashboard.manifest?.updatedAt||dashboard.manifest?.publishedAt||dashboard.manifest?.builtAt||"Never"]]}/></section><section className="admin-card"><div className="admin-card-head"><div><h2>Cloud Sync Controls</h2><p>Every operation remains scoped to this Race Upshot event and stored provider UUID.</p></div></div><div className="hub-operation-grid">{operations.map(([action,label,description])=><article key={action} className={/HARD|DELETE/.test(action)?"danger":""}><div><b>{label}</b><p>{description}</p></div><button className={`button ${action==="FULL_REBUILD"?"button-primary":""}`} disabled={Boolean(busy)} onClick={()=>void run(action)}>{busy===action?<Loader2 className="spin"/>:<RefreshCw/>} {busy===action?"Running…":label}</button></article>)}</div></section>{output&&<section className="admin-card"><h2>Latest Operation Result</h2><pre className="hub-json-output">{output}</pre></section>}</div>}
    {tab==="logs"&&<LiveTrackingLogsPanel event={{id:event.id,name:event.name,eventUuid:connection.eventUuid}} dashboard={dashboard} busy={busy} run={run} refresh={refreshDashboard} resetCanonical={reset} viewCanonical={()=>loadCanonical()}/>}
    {tab==="notifications"&&<NotificationPanel event={event} config={config} update={update} save={save} category={notificationCategory} setCategory={value=>{setNotificationCategory(value);setNotificationSummary(notificationSummaries[value]??null);}} summary={notificationSummary} summaries={notificationSummaries} refresh={refreshNotificationTracing} run={notifyFinishers} busy={busy}/>}
    {tab==="export"&&<ExportPanel event={event} connection={connection} dashboard={dashboard} fields={exportFields} setFields={setExportFields} download={exportExcel}/>}
    {tab==="reset"&&<ResetCanonicalPanel event={event} snapshot={canonicalSnapshot} busy={busy==="reset"||canonicalBusy} refresh={()=>loadCanonical(false)} reset={reset}/>}
    {tab==="upload"&&<div className="hub-embedded-results"><div className="admin-card-head"><div><h2><UploadCloud/> Publish Official Results</h2><p>Upload a completed spreadsheet and rebuild official KV results and rankings.</p></div></div><PublishResults events={[event]} resultSets={{[event.slug]:event.results}}/></div>}
    {canonicalOpen&&canonicalSnapshot&&<CanonicalFilesModal eventName={event.name} snapshot={canonicalSnapshot} busy={canonicalBusy||busy==="FULL_REBUILD"} close={()=>setCanonicalOpen(false)} refresh={()=>loadCanonical(false)} rebuild={rebuildCanonical}/>}
  </div>;
}

function Facts({rows}:{rows:Array<[string,string|number]>}){return <div className="hub-provider-grid">{rows.map(([label,value])=><span key={label}><small>{label}</small><b>{value}</b></span>)}</div>}
function ResetCanonicalPanel({event,snapshot,busy,refresh,reset}:{event:HubEvent;snapshot:CanonicalAdminSnapshot|null;busy:boolean;refresh:()=>Promise<void>;reset:()=>Promise<void>}){const counts=snapshot?.counts;return <section className="admin-card hub-reset-card"><div className="admin-card-head"><div><h2><Database/> Reset Canonical Data</h2><p>Clear generated live timing for the selected event without deleting its Feibot setup, mappings, course, or roster.</p></div><span className="status-pill">Event-scoped only</span></div><div className="hub-reset-event"><b>{event.name}</b><code>{event.id}</code></div><Facts rows={[["Canonical keys",counts?.canonicalKeys??"…"],["Notification markers",counts?.notificationMarkers??"…"],["User reverse indexes",counts?.userReverseIndexes??"…"],["Total targeted",counts?.totalTargeted??"…"]]}/><div className="hub-reset-summary"><b>This reset removes</b><p>The active manifest, versioned snapshots, participant live state, accepted timing/results, leaderboards, derived timing decisions, runtime projections, and notification dedupe markers.</p><b>Preserved</b><ul><li>Feibot credentials and event link</li><li>Contest, participant, leg and split mappings</li><li>Timing configuration, course maps and provider roster</li><li>Raw provider reads, manual timing overrides, watchlists and chip-assignment audit history</li></ul></div><div className="hub-reset-warning"><AlertTriangle/><span><b>Live tracking becomes unavailable until rebuilt</b><small>After reset, run Full Rebuild in Feibot Sync to publish a fresh complete canonical version before starting or testing the race.</small></span></div><div className="hub-reset-actions"><button className="button" disabled={busy} onClick={()=>void refresh()}><RefreshCw className={busy?"spin":""}/> Refresh count</button><button className="button cms-danger-button" disabled={busy||!counts?.totalTargeted} onClick={()=>void reset()}><Trash2/> Reset canonical data</button></div></section>}
function CanonicalFilesModal({eventName,snapshot,busy,close,refresh,rebuild}:{eventName:string;snapshot:CanonicalAdminSnapshot;busy:boolean;close:()=>void;refresh:()=>Promise<void>;rebuild:()=>Promise<void>}){const [selectedKey,setSelectedKey]=useState(snapshot.files.find(file=>file.label==="Participant index")?.key??snapshot.files[0]?.key??"");const selected=snapshot.files.find(file=>file.key===selectedKey)??snapshot.files[0];const found=snapshot.files.filter(file=>file.exists).length;const version=snapshot.manifest?.activeVersion||snapshot.manifest?.version||"";const copy=async()=>{if(selected?.value)await navigator.clipboard.writeText(selected.value);};return <div className="hub-canonical-modal-backdrop" role="presentation" onMouseDown={close}><section className="hub-canonical-modal" role="dialog" aria-modal="true" aria-label="Event canonical files in KV" onMouseDown={e=>e.stopPropagation()}><header><div><h2><Database/> Event Canonical Files in KV</h2><p>Exact active, version-pinned Race Upshot artifacts for {eventName}. Provider credentials and raw payloads are not included.</p></div><div className="form-actions"><button className="button button-primary" disabled={busy} onClick={()=>void rebuild()}><RefreshCw className={busy?"spin":""}/> {busy?"Rebuilding…":"Rebuild canonical"}</button><button onClick={close} aria-label="Close canonical files"><X/></button></div></header><div className="hub-canonical-overview"><span><small>Event</small><b>{snapshot.eventId}</b></span><span><small>Active version</small><b>{version||"—"}</b></span><span><small>Build validity</small><b className={snapshot.manifest?.completeBuildValid?"valid":"invalid"}>{snapshot.manifest?.completeBuildValid?"COMPLETE":"NOT VALID"}</b></span><span><small>Canonical files found</small><b>{found} of {snapshot.files.length} expected</b></span></div><div className={`hub-canonical-diagnostics ${snapshot.manifest?.completeBuildValid?"valid":"invalid"}`}><b>Latest canonical build diagnostics</b><span>Version: {version||"Not published"}</span><span>Build status: {snapshot.manifest?.completeBuildValid?"complete and published":"missing or invalid"}</span><span>Participants: {snapshot.manifest?.participantCount??0}</span><span>Provider: {snapshot.manifest?.provider||"—"}</span><span>Participant version: {snapshot.manifest?.participantVersion??"Legacy"}</span><span>Timing version: {snapshot.manifest?.timingVersion??0}</span><span>Leaderboard version: {snapshot.manifest?.leaderboardVersion??0}</span><span>Course version: {snapshot.manifest?.courseVersion??"Legacy"}</span><span>Published: {snapshot.manifest?.publishedAt?new Date(snapshot.manifest.publishedAt).toLocaleString():"—"}</span><span>Updated: {snapshot.manifest?.updatedAt?new Date(snapshot.manifest.updatedAt).toLocaleString():"—"}</span><span>History retained: {snapshot.history?.versions.length??0} older versions · {snapshot.history?.files??0} files</span></div><div className="hub-canonical-browser"><aside><b>KV keys</b>{version&&<code>{`raceupshot:canonical:event:${snapshot.eventId}:version:${version}:`}</code>}{snapshot.files.map(file=><button key={file.key} className={selected?.key===file.key?"active":""} onClick={()=>setSelectedKey(file.key)}><strong>{file.label}{file.exists?"":" · Missing"}</strong><code>{file.key}</code><small>{file.exists?`${(file.size/1024).toFixed(1)} KB`:"Not found"}</small></button>)}</aside><main><header><div><b>{selected?.label||"Canonical data"}</b><code>{selected?.key||"No active key"}</code></div><div><button className="button" disabled={!selected?.value} onClick={()=>void copy()}><Copy/> Copy JSON</button><button className="button" disabled={busy} onClick={()=>void refresh()}><RefreshCw className={busy?"spin":""}/> Refresh</button></div></header><pre>{selected?.value||"No canonical value is available for this event."}</pre>{selected?.truncated&&<small>Preview truncated at 1 MB.</small>}</main></div></section></div>}
function ConnectionsSetupPanel(props:{event:HubEvent;connection:FeibotAdminConnection;dashboard:FeibotOperationsDashboard;platform:EventPlatformSettings;credentials:{accessKey:string;secretKey:string;eventUuid:string;baseUrl:string};setCredentials:(x:{accessKey:string;secretKey:string;eventUuid:string;baseUrl:string})=>void;connectionLabel:string;setConnectionLabel:(x:string)=>void;connectionFormOpen:boolean;editingConnectionId:string|null;addConnection:()=>void;manageConnection:(card:FeibotAdminConnection["connections"][number])=>void;closeConnectionForm:()=>void;account:FeibotAccountCredentialStatus;accountForm:{accountId:string;accessKey:string;secretKey:string;baseUrl:string};setAccountForm:(x:{accountId:string;accessKey:string;secretKey:string;baseUrl:string})=>void;busy:string;connect:(refresh?:boolean,source?:"EVENT"|"ACCOUNT")=>Promise<void>;disconnect:(id?:string|null)=>Promise<void>;verifyConnection:(id?:string|null)=>Promise<void>;accountAction:(action:"save"|"test"|"delete")=>Promise<void>;setPublic:(enabled:boolean)=>Promise<void>;refresh:()=>Promise<unknown>}) {
  const {event,connection,dashboard,platform,credentials,setCredentials,connectionLabel,setConnectionLabel,connectionFormOpen,editingConnectionId,addConnection,manageConnection,closeConnectionForm,account,accountForm,setAccountForm,busy,connect,disconnect,verifyConnection,accountAction,setPublic,refresh}=props;
  const eventUuid=credentials.eventUuid||connection.eventUuid;
  const editing=connection.connections.find(item=>item.connectionId===editingConnectionId);
  const canSave=Boolean(eventUuid&&(editing||account.configured||credentials.accessKey&&credentials.secretKey));
  return <div className="hub-two-column"><div className="hub-stack">
    <section className="admin-card"><div className="admin-card-head"><div><h2>Event Configuration</h2><p>Link this Race Upshot event to one or more Feibot event connections for live tracking integration.</p></div><button className="button" disabled={Boolean(busy)||!connection.connectionId} onClick={()=>void connect(true)}><RefreshCw/> Refresh Feibot events</button></div>
      <div className="hub-connections-heading"><div><b>Feibot Connections</b><p>Each Feibot event keeps its own scoped API key, provider data and category mapping.</p></div><button className="button button-primary" onClick={addConnection}><Plus/> Add Feibot Connection</button></div>
      <div className="hub-connection-summary"><div><span>Active Feibot Connections</span><strong>{connection.connections.length} active</strong></div>{connection.connections.map(card=><article key={card.connectionId} className={card.connectionId===connection.connectionId?"selected":""}><div><b>{card.label||card.eventName||card.eventUuid}</b><small>Feibot Event</small><code>{card.eventUuid}</code></div><div><span className={`status-pill ${card.connected?"status-live":""}`}>{card.credentialSource==="ACCOUNT"?"Account Key Connected":"API Key Connected"}</span><small>Race Date</small><b>{card.raceDate||"—"}</b></div><div><small>Categories</small><b>{card.contests.length} categories</b><div className="hub-category-chips">{card.contests.map(contest=><span key={contest.uuid}>{contest.name}</span>)}</div></div><div className="hub-card-actions"><button className="button" onClick={()=>manageConnection(card)}>Manage</button><button className="button" disabled={Boolean(busy)} onClick={()=>void verifyConnection(card.connectionId)}><Check/> Verify</button><button className="button cms-danger-button" disabled={Boolean(busy)} onClick={()=>void disconnect(card.connectionId)}><Trash2/> Delete</button></div></article>)}</div>
      {connectionFormOpen&&<div className="hub-connection-editor"><div className="admin-card-head"><div><h3>{editingConnectionId?"Manage Feibot Connection":"Add Feibot Connection"}</h3><p>Credentials are stored server-side and scoped to this exact Feibot UUID.</p></div><button className="button" onClick={closeConnectionForm}><X/> Close</button></div><div className="form-grid"><div className="field"><label>Connection name</label><input value={connectionLabel} placeholder="Bergman Triathlon" onChange={e=>setConnectionLabel(e.target.value)}/></div><div className="field"><label>API Base URL</label><input value="https://apicn.feibot.com" readOnly aria-readonly="true" className="locked-input"/></div><div className="field"><label>Feibot Event UUID</label><input value={credentials.eventUuid} readOnly={Boolean(editingConnectionId)} placeholder="Event UUID" onChange={e=>setCredentials({...credentials,eventUuid:e.target.value})}/></div><div className="field"><label>Access Key</label><input type="password" value={credentials.accessKey} placeholder={editing?.accessKeyMasked||"Access Key"} onChange={e=>setCredentials({...credentials,accessKey:e.target.value})}/></div><div className="field"><label>Secret Key</label><input type="password" value={credentials.secretKey} placeholder={editing?"Stored securely · enter both keys to change":"Secret Key"} onChange={e=>setCredentials({...credentials,secretKey:e.target.value})}/></div></div><div className="form-actions"><button className="button button-primary" disabled={Boolean(busy)||!canSave} onClick={()=>void connect(false,"EVENT")}><KeyRound/> {editing?"Save connection changes":"Add Feibot Connection"}</button>{editing&&<button className="button" disabled={Boolean(busy)} onClick={()=>void verifyConnection(editing.connectionId)}><Check/> Verify Connection</button>}</div></div>}
    </section>
    <AccountCredentialsPanel status={account} form={accountForm} setForm={setAccountForm} action={accountAction} eventUuid={eventUuid} busy={busy} active={connection.configured&&connection.credentialSource==="ACCOUNT"} linkAccount={()=>connect(false,"ACCOUNT")}/>
    <section className="admin-card"><div className="admin-card-head"><div><h2>Public Live Tracking</h2><p>Enable the event feed and control public athlete discovery.</p></div><span className={`status-pill ${platform.live.publicLiveTrackingEnabled?"status-live":""}`}>{platform.live.publicLiveTrackingEnabled?"Athletes Visible":"Disabled"}</span></div><p>{platform.live.publicLiveTrackingEnabled?"Public athlete search and tracking are enabled.":"Athletes remain hidden from the public feed."}</p><div className="form-actions"><button className="button button-primary" disabled={!dashboard.ready||platform.live.publicLiveTrackingEnabled} onClick={()=>void setPublic(true)}>Enable Live Tracking</button><button className="button" disabled={!platform.live.publicLiveTrackingEnabled} onClick={()=>void setPublic(false)}>Disable Live Tracking</button></div>{!dashboard.ready&&<p className="hub-lock-note">The enable action stays locked until every readiness gate is complete.</p>}</section>
    <Provider event={event} connection={connection} dashboard={dashboard}/>
  </div><aside className="admin-card hub-readiness"><div className="admin-card-head"><div><h2>Readiness gates</h2><p>Live tracking can only be enabled after all checks pass.</p></div></div><div className="hub-scope"><small>FEIBOT CONNECTION SCOPE</small><b>{connection.label||connection.eventName||event.name} · {connection.eventUuid||"Not selected"}</b></div>{dashboard.gates.map(g=><article key={g.id}><span className={g.ready?"ready":"pending"}>{g.ready?<Check/>:<XCircle/>}</span><div><b>{g.label}</b><p>{g.detail}</p></div><em>{g.ready?"Ready":"Pending"}</em></article>)}<button className="button" onClick={()=>void refresh()}><RefreshCw/> Recheck connection</button></aside></div>;
}
function AccountCredentialsPanel({status,form,setForm,action,eventUuid,busy,active,linkAccount}:{status:FeibotAccountCredentialStatus;form:{accountId:string;accessKey:string;secretKey:string;baseUrl:string};setForm:(x:{accountId:string;accessKey:string;secretKey:string;baseUrl:string})=>void;action:(x:"save"|"test"|"delete")=>Promise<void>;eventUuid:string;busy:string;active:boolean;linkAccount:()=>Promise<void>}){return <section className="admin-card"><div className="admin-card-head"><div><h2>AK-ACCOUNT (Account Credentials)</h2><p>Save one account key, then explicitly link the selected Feibot event UUID.</p></div><span className={`status-pill ${status.connected?"status-live":""}`}>{status.configured?(status.connected?"Verified":"Configured"):"Not configured"}</span></div><div className="form-grid"><div className="field"><label>Account ID</label><input value={form.accountId} placeholder="feibot" onChange={e=>setForm({...form,accountId:e.target.value})}/></div><div className="field"><label>API Base URL</label><input value="https://apicn.feibot.com" readOnly aria-readonly="true" className="locked-input"/></div><div className="field"><label>Access Key</label><input type="password" value={form.accessKey} placeholder={status.accessKeyMasked||"Enter Account Access Key"} onChange={e=>setForm({...form,accessKey:e.target.value})}/></div><div className="field"><label>Secret Key</label><input type="password" value={form.secretKey} placeholder={status.configured?"Stored securely · enter both keys to change":"Enter Account Secret Key"} onChange={e=>setForm({...form,secretKey:e.target.value})}/></div></div>{status.message&&<p className="hub-account-status">Last test: {status.message}{status.lastTestedAt?` · ${new Date(status.lastTestedAt).toLocaleString()}`:""}</p>}<div className="form-actions"><button className="button button-primary" disabled={Boolean(busy)||!form.accountId||!form.accessKey||!form.secretKey} onClick={()=>void action("save")}><Save/> {status.configured?"Change Account Key":"Save Account Key"}</button><button className="button" disabled={Boolean(busy)||!status.configured||!eventUuid} onClick={()=>void action("test")}><RefreshCw/> Test Account Key</button><button className="button" disabled={Boolean(busy)||!status.configured||!eventUuid||active} onClick={()=>void linkAccount()}><KeyRound/> {active?"Account Key Linked":"Use Account Key for This Event"}</button>{status.configured&&<button className="button cms-danger-button" disabled={Boolean(busy)} onClick={()=>void action("delete")}><Trash2/> Delete Account Key</button>}</div><p className="hub-lock-note">Changing the account key requires both new key fields. Deleting it preserves event mappings and canonical data.</p></section>}
function NotificationPanel({event,config,update,save,category,setCategory,summary,summaries,refresh,run,busy}:{event:HubEvent;config:LiveTrackingHubConfig;update:(x:LiveTrackingHubConfig)=>void;save:()=>Promise<void>;category:string;setCategory:(x:string)=>void;summary:ResultEmailSummary|null;summaries:Record<string,ResultEmailSummary>;refresh:()=>Promise<void>;run:(action:"preview"|"send",channels?:FinisherNotificationChannel[],retryFailed?:boolean,category?:string,bib?:string,forceResend?:boolean)=>Promise<void>;busy:string}) {
  const [finisherSearch,setFinisherSearch]=useState("");
  const [deliveryFilter,setDeliveryFilter]=useState("ALL");
  const [exactBib,setExactBib]=useState("");
  const publishedCategories=Object.entries(summaries).filter(([name,row])=>name!=="Overall"&&row.total>0).map(([name])=>name);
  const categories=["Overall",...(publishedCategories.length?publishedCategories:event.categories.filter(x=>x!=="Overall"))];
  const contests=categories.filter(x=>x!=="Overall");
  const overall=summaries.Overall??summary;
  const ready=config.notifications.enabled&&config.notifications.finishersEnabled;
  const emailReady=ready&&config.notifications.emailEnabled&&Boolean(config.notifications.emailTemplateId||(config.notifications.emailTriathlonTemplateId&&config.notifications.emailSingleSportTemplateId));
  const whatsappReady=ready&&config.notifications.whatsappEnabled&&Boolean(config.notifications.whatsappCampaignName||(config.notifications.whatsappTriathlonCampaignName&&config.notifications.whatsappSingleSportCampaignName));
  const visibleFinishers=(summaries[category]??(category==="Overall"?overall:null))?.finishers??[];
  const searchedFinishers=visibleFinishers.filter(finisher=>(!finisherSearch.trim()||[finisher.name,finisher.bib,finisher.category,finisher.email,finisher.mobile].some(value=>value.toLowerCase().includes(finisherSearch.trim().toLowerCase())))&&(deliveryFilter==="ALL"||finisher.emailStatus===deliveryFilter||finisher.whatsappStatus===deliveryFilter));
  const deliveryLabel=(status:string)=>status==="ACCEPTED"?"Provider accepted":status==="UNCONFIRMED"?"Unconfirmed":status==="FAILED"?"Failed":status==="INELIGIBLE"?"Ineligible":status==="MISSING_CONTACT"?"Missing contact":status==="REVIEW_REQUIRED"?"Review identity":"Not sent";
  const displayAttempt=(value?:string)=>value?new Date(value).toLocaleString():"—";
  const skipped=(row:ResultEmailSummary|null|undefined)=>row?.channels?row.channels.email.pending+row.channels.email.failed+row.channels.email.ineligible+row.channels.whatsapp.pending+row.channels.whatsapp.failed+row.channels.whatsapp.ineligible:0;
  const editContact=async(finisher:FinisherTraceRow)=>{const email=window.prompt(`Email for ${finisher.name} (${finisher.resultId??finisher.id})`,finisher.email);if(email===null)return;const mobile=window.prompt("WhatsApp number",finisher.mobile);if(mobile===null)return;const reason=window.prompt("Audit reason for this contact correction (at least 5 characters)");if(!reason||reason.trim().length<5)return;const response=await fetch(`/api/admin/results/${encodeURIComponent(event.id)}/contact`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({category:finisher.category,resultId:finisher.resultId??finisher.id,email,mobile,reason})});const payload=await response.json() as {ok?:boolean;error?:string|{message?:string}};if(!response.ok||!payload.ok){window.alert(typeof payload.error==="string"?payload.error:payload.error?.message??"Unable to update contact.");return;}await refresh();};
  const downloadCsv=()=>{
    const header=["Result ID","Finisher","BIB","Contest","Finish Time","Eligibility / Skip Reason","Email","Email Status","Email Time","Email Attempts","WhatsApp","WhatsApp Status","WhatsApp Time","WhatsApp Attempts","Contact Audit","Trigger","Actor","Last Attempt"];
    const rows=(overall?.finishers??[]).map(finisher=>[finisher.resultId??finisher.id,finisher.name,finisher.bib,finisher.category,finisher.finishTime,finisher.eligibilityReason??"",finisher.email,deliveryLabel(finisher.emailStatus),finisher.emailAttemptedAt??"",JSON.stringify(finisher.emailAttempts??[]),finisher.mobile,deliveryLabel(finisher.whatsappStatus),finisher.whatsappAttemptedAt??"",JSON.stringify(finisher.whatsappAttempts??[]),JSON.stringify(finisher.contactAudit??[]),finisher.trigger,finisher.actor,finisher.lastAttemptedAt??""]);
    const csv=[header,...rows].map(row=>row.map(value=>{const safe=/^[=+@\-\t\r]/.test(String(value))?`'${value}`:String(value);return `"${safe.replaceAll('"','""')}"`;}).join(",")).join("\n");
    const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));
    const link=document.createElement("a");link.href=url;link.download=`${event.slug}-finisher-notification-tracing.csv`;link.click();URL.revokeObjectURL(url);
  };
  return <div className="hub-stack">
    <section className="admin-card hub-notification-config">
      <div className="admin-card-head"><div><h2>Finisher Notification Tracing</h2><p>Provider acceptance is not confirmed inbox delivery. Live sending is disabled until explicitly enabled server-side.</p></div><div className="form-actions"><button className="button" disabled={Boolean(busy)} onClick={()=>void refresh()}><RefreshCw/> Refresh</button><button className="button" disabled={!overall} onClick={downloadCsv}><Download/> Download CSV</button></div></div>
      <div className="hub-notification-stats">
        <article className="total"><span><Check/> Published result rows</span><strong>{overall?.total??0}</strong></article>
        <article className="sent"><span><Mail/> Emails accepted</span><strong>{overall?.channels?.email.accepted??0}</strong></article>
        <article className="sent"><span><MessageCircle/> WhatsApp accepted</span><strong>{overall?.channels?.whatsapp.accepted??0}</strong></article>
        <article className="skipped"><span><AlertTriangle/> Not Sent / Skipped</span><strong>{skipped(overall)}</strong></article>
      </div>
      <details className="hub-notification-settings">
        <summary>Notification settings <span>{ready?"Enabled":"Needs setup"}</span></summary>
        <div className="platform-toggle-grid compact">{(["enabled","finishersEnabled"] as const).map(key=><label className="platform-toggle-row" key={key}><span><b>{key==="enabled"?"Notifications enabled":"Finisher notifications"}</b></span><input type="checkbox" checked={config.notifications[key]} onChange={e=>update({...config,notifications:{...config.notifications,[key]:e.target.checked}})}/><i/></label>)}</div>
        <div className="form-grid"><div className="field"><label>Campaign name</label><input value={config.notifications.campaignName} placeholder="Event finishers" onChange={e=>update({...config,notifications:{...config.notifications,campaignName:e.target.value}})}/></div><div className="field"><label>Inspect contest / category</label><select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(x=><option key={x}>{x}</option>)}</select></div></div>
        <div className="hub-notification-channels"><article><label className="platform-toggle-row"><span><b>Email</b><small>Use a saved Bergtecno email template UUID.</small></span><input type="checkbox" checked={config.notifications.emailEnabled} onChange={e=>update({...config,notifications:{...config.notifications,emailEnabled:e.target.checked}})}/><i/></label><div className="field"><label>Fallback Bergtecno email template ID</label><input value={config.notifications.emailTemplateId} placeholder="Template UUID" onChange={e=>update({...config,notifications:{...config.notifications,emailTemplateId:e.target.value}})}/><small>Available parameters: eventName, athleteName, bib, finish_time, race_breakdown.</small></div></article><article><label className="platform-toggle-row"><span><b>WhatsApp</b><small>AiSensy approved results campaign.</small></span><input type="checkbox" checked={config.notifications.whatsappEnabled} onChange={e=>update({...config,notifications:{...config.notifications,whatsappEnabled:e.target.checked}})}/><i/></label><div className="field"><label>Fallback AiSensy API campaign</label><input value={config.notifications.whatsappCampaignName||""} placeholder="Campaign name" onChange={e=>update({...config,notifications:{...config.notifications,whatsappCampaignName:e.target.value}})}/></div></article></div>
        <div className="form-grid"><div className="field"><label>Triathlon email template</label><input value={config.notifications.emailTriathlonTemplateId??""} onChange={e=>update({...config,notifications:{...config.notifications,emailTriathlonTemplateId:e.target.value}})}/></div><div className="field"><label>Single-sport email template</label><input value={config.notifications.emailSingleSportTemplateId??""} onChange={e=>update({...config,notifications:{...config.notifications,emailSingleSportTemplateId:e.target.value}})}/></div><div className="field"><label>Triathlon WhatsApp campaign</label><input value={config.notifications.whatsappTriathlonCampaignName??""} onChange={e=>update({...config,notifications:{...config.notifications,whatsappTriathlonCampaignName:e.target.value}})}/></div><div className="field"><label>Single-sport WhatsApp campaign</label><input value={config.notifications.whatsappSingleSportCampaignName??""} onChange={e=>update({...config,notifications:{...config.notifications,whatsappSingleSportCampaignName:e.target.value}})}/></div></div>
        <label className="platform-toggle-row"><span><b>Registration confirmations</b><small>Only on a persisted admin finalization status transition. Disabled by default.</small></span><input type="checkbox" checked={config.notifications.registrationEnabled??false} onChange={e=>update({...config,notifications:{...config.notifications,registrationEnabled:e.target.checked}})}/><i/></label>
        <div className="form-grid"><div className="field"><label>Registration email template</label><input value={config.notifications.registrationEmailTemplateId??""} onChange={e=>update({...config,notifications:{...config.notifications,registrationEmailTemplateId:e.target.value}})}/></div><div className="field"><label>Registration WhatsApp campaign</label><input value={config.notifications.registrationWhatsAppCampaignName??""} onChange={e=>update({...config,notifications:{...config.notifications,registrationWhatsAppCampaignName:e.target.value}})}/></div></div>
        <p className="hub-lock-note">WhatsApp parameters: 1 name, 2 category, 3 event, 4 category, 5 BIB, 6 finish time, 7 leg breakdown.</p>
        <div className="form-actions"><button className="button button-primary" onClick={()=>void save()}><Save/> Save notification settings</button></div>
      </details>
    </section>
    <section className="admin-card">
      <div className="admin-card-head"><div><h2>Contest-wise manual send</h2><p>Send only missing or failed notifications. Provider-accepted recipients are always protected from duplication.</p></div><span className="status-pill">{contests.length} contests</span></div>
      <div className="hub-notification-contests">{contests.map(name=>{const row=summaries[name];const email=row?.channels?.email;const whatsapp=row?.channels?.whatsapp;const resendable=(emailReady?(email?.eligible??0):0)+(whatsappReady?(whatsapp?.eligible??0):0);return <article key={name}><div className="hub-notification-contest-copy"><h3>{name}</h3><p>Email {email?.accepted??0} · WhatsApp {whatsapp?.accepted??0} · Not sent/skipped {skipped(row)}</p><b>{row?.total??0} finishers</b></div><div className="hub-notification-contest-actions"><button type="button" className="button" disabled={Boolean(busy)||!emailReady||!email?.pending} onClick={()=>void run("send",["EMAIL"],false,name)}><Mail/> Missing Email</button><button type="button" className="button notification-send-whatsapp" disabled={Boolean(busy)||!whatsappReady||!whatsapp?.pending} onClick={()=>void run("send",["WHATSAPP"],false,name)}><MessageCircle/> Missing WhatsApp</button><button type="button" className="button notification-send-primary" disabled={Boolean(busy)||(!emailReady&&!whatsappReady)||(!(email?.pending)&&!(whatsapp?.pending))} onClick={()=>void run("send",[...(emailReady?["EMAIL" as const]:[]),...(whatsappReady?["WHATSAPP" as const]:[])],false,name)}><Send/> All Missing</button><button type="button" className="button notification-send-danger" disabled={Boolean(busy)||!resendable} onClick={()=>void run("send",[...(emailReady?["EMAIL" as const]:[]),...(whatsappReady?["WHATSAPP" as const]:[])],true,name,undefined,true)}><RefreshCw/> Resend All Eligible</button></div></article>})}</div>
      {!contests.length&&<div className="admin-empty">No event contests are configured yet.</div>}
      <p className="hub-lock-note">Each action processes the next 10 recipients per selected channel. Rows marked “Review identity” lack a source-supplied participant or result ID and are never auto-sent; select the exact row for a confirmed manual send.</p>
    </section>
    <section className="admin-card hub-notification-recovery">
      <div className="admin-card-head"><div><h2>Send one missing finisher</h2><p>Use this when a confirmed canonical finisher has no notification log row yet. Eligibility and accepted final-split timing are checked again before either provider is called.</p></div></div>
      <p>Select the exact published result in the log below. A BIB alone is not a unique recipient identity.</p>
    </section>
    <section className="admin-card hub-finisher-trace">
      <div className="admin-card-head"><div><h2>Finisher delivery log</h2><p>Every confirmed finisher and the exact reason each channel has or has not sent.</p></div></div>
      <div className="hub-notification-log-tools"><label><Search/><input value={finisherSearch} onChange={event=>setFinisherSearch(event.target.value)} placeholder="Search name, BIB, contest, email or WhatsApp"/></label><select aria-label="Filter by contest" value={category} onChange={event=>setCategory(event.target.value)}>{categories.map(name=><option key={name}>{name}</option>)}</select><select aria-label="Filter by delivery state" value={deliveryFilter} onChange={event=>setDeliveryFilter(event.target.value)}>{["ALL","PENDING","ACCEPTED","FAILED","UNCONFIRMED","MISSING_CONTACT","INELIGIBLE","REVIEW_REQUIRED"].map(status=><option key={status} value={status}>{status.replaceAll("_"," ")}</option>)}</select><b>Showing {searchedFinishers.length} of {visibleFinishers.length}</b></div>
      <div className="hub-finisher-trace-scroll"><table><thead><tr><th>Finisher</th><th>Contest</th><th>Email</th><th>Email Time</th><th>WhatsApp</th><th>WhatsApp Time</th><th>Trigger</th><th>Last Attempt</th><th>Actions</th></tr></thead><tbody>{searchedFinishers.map(finisher=>{const resendChannels=[...(emailReady&&finisher.emailStatus!=="MISSING_CONTACT"&&finisher.emailStatus!=="INELIGIBLE"?["EMAIL" as const]:[]),...(whatsappReady&&finisher.whatsappStatus!=="MISSING_CONTACT"&&finisher.whatsappStatus!=="INELIGIBLE"?["WHATSAPP" as const]:[])];return <tr key={`${finisher.category}:${finisher.resultId??finisher.id}`}><td><b>{finisher.name}</b><small>BIB {finisher.bib} · Result {finisher.resultId??finisher.id}</small><small>{finisher.eligibilityReason||"Eligible"}</small></td><td>{finisher.category}</td><td><span className={`notification-state ${finisher.emailStatus.toLowerCase()}`}>{deliveryLabel(finisher.emailStatus)}</span><small>{finisher.email||finisher.emailError||"No email"}</small></td><td>{displayAttempt(finisher.emailAttemptedAt)}</td><td><span className={`notification-state ${finisher.whatsappStatus.toLowerCase()}`}>{deliveryLabel(finisher.whatsappStatus)}</span><small>{finisher.mobile||finisher.whatsappError||"No mobile"}</small></td><td>{displayAttempt(finisher.whatsappAttemptedAt)}</td><td><b className="notification-trigger">{finisher.trigger}</b><small>{finisher.actor}</small></td><td>{displayAttempt(finisher.lastAttemptedAt)}</td><td><button type="button" className="button notification-row-action" disabled={Boolean(busy)} onClick={()=>void editContact(finisher)}>Edit contact</button><button type="button" className="button notification-row-action" disabled={Boolean(busy)||!resendChannels.length} onClick={()=>void run("send",resendChannels,false,finisher.category,finisher.resultId??finisher.id)}><Send/> Send missing</button><button type="button" className="button notification-row-action" disabled={Boolean(busy)||!resendChannels.length} onClick={()=>void run("send",resendChannels,true,finisher.category,finisher.resultId??finisher.id,true)}><RefreshCw/> Resend</button><details><summary>Audit</summary><pre>{JSON.stringify({email:finisher.emailAttempts,whatsapp:finisher.whatsappAttempts,contact:finisher.contactAudit},null,2)}</pre></details></td></tr>})}</tbody></table></div>
      {!searchedFinishers.length&&<div className="admin-empty">No notification records match this search.</div>}
    </section>
  </div>;
}
function ExportPanel({event,connection,dashboard,fields,setFields,download}:{event:HubEvent;connection:FeibotAdminConnection;dashboard:FeibotOperationsDashboard;fields:Set<string>;setFields:(value:Set<string>)=>void;download:()=>void}){return <section className="admin-card"><div className="admin-card-head"><div><h2>Export Live Results</h2><p>Select exactly which athlete, ranking and result fields are included in the Excel workbook.</p></div><span className="status-pill">{event.results.length} athletes</span></div><div className="hub-export-actions"><button className="button" onClick={()=>setFields(new Set(exportColumns.map(([key])=>key)))}>Select all</button><button className="button" onClick={()=>setFields(new Set(["bib","name","category","rank","finishTime","status"]))}>Recommended fields</button><button className="button" onClick={()=>setFields(new Set())}>Clear</button><b>{fields.size} columns selected</b></div><div className="hub-export-fields">{exportColumns.map(([key,label])=><label key={key}><input type="checkbox" checked={fields.has(key)} onChange={e=>{const next=new Set(fields);if(e.target.checked)next.add(key);else next.delete(key);setFields(next);}}/> {label}</label>)}</div><Facts rows={[["Provider Event UUID",connection.eventUuid||"—"],["Canonical Version",dashboard.manifest?.activeVersion||dashboard.manifest?.version||"—"]]}/><button className="button button-primary" disabled={!event.results.length||!fields.size} onClick={download}><Download/> Download Excel</button></section>}
function Provider({event,connection,dashboard}:{event:RaceEvent;connection:FeibotAdminConnection;dashboard:FeibotOperationsDashboard}){return <section className="admin-card"><div className="admin-card-head"><div><h2>Provider Status</h2><p>Current secure backend and canonical state.</p></div><span className={`status-pill ${connection.connected?"status-live":""}`}>{connection.status.replaceAll("_"," ")}</span></div><Facts rows={[["Provider","Feibot"],["Credential Source",connection.credentialSource?`${connection.credentialSource} credentials`:"Not configured"],["Authentication",connection.connected?"Verified":"Not verified"],["Cloud Timing Rules",`${dashboard.rules.contests} contests · ${dashboard.rules.splits} splits · ${dashboard.rules.timingPoints} points`],["Participants",`${connection.counts.participants} imported`],["Active Source","Feibot Cloud API → Canonical KV"],["Canonical Version",dashboard.manifest?.activeVersion||dashboard.manifest?.version||"Not built"],["Last Sync",connection.lastConnectedAt||"Never"],["Race Upshot Event",event.id]]}/></section>}
function StartPanel({connection,dashboard,config,update,save,refresh,busy}:{connection:FeibotAdminConnection;dashboard:FeibotOperationsDashboard;config:LiveTrackingHubConfig;update:(x:LiveTrackingHubConfig)=>void;save:()=>Promise<void>;refresh:()=>Promise<unknown>;busy:string}) {
  const contests=dashboard.timingContests??[];
  const [contestUuid,setContestUuid]=useState(contests[0]?.uuid??connection.contests[0]?.uuid??"");
  const contest=contests.find(item=>item.uuid===contestUuid)??contests[0];
  const providerGunStart=contest?.gunStartAt&&Number.isFinite(Date.parse(contest.gunStartAt))?new Date(contest.gunStartAt).toISOString():null;
  const displayedGunStart=providerGunStart??config.start.gunStartAt;
  const modeCopy={GUN:"Automatically uses the official contest start time from Feibot. If unavailable, it uses the saved event start time.",WAVE:"Uses the configured wave baseline while preserving each athlete's accepted RFID reads.",CHIP:"Each athlete's race clock begins at the first valid START-mat passage after the permitted start time."} as const;
  const nums=[["deduplicationSeconds","Deduplication Window","Seconds · default 5"],["validStartWindowMinutes","Valid Start Window","Minutes · default 30"],["dnsGraceMinutes","DNS Grace Period","Minutes after official start · default 60"],["passageGroupingGapSeconds","Passage Grouping Gap","Seconds · default 3"],["reorderBufferMs","Timing Reorder Buffer","Milliseconds · default 2000"],["minimumFinishGapSeconds","Minimum Finish Gap","Seconds after START · default 300"]] as const;
  const flags:[[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?],[keyof LiveTrackingHubConfig["start"],string,string?]]=[
    ["ignoreReadsBeforeStart","Ignore reads before official start"],
    ["lockFirstAcceptedStart","Lock first accepted start"],
    ["storeEveryStartHit","Store every START reader hit"],
    ["requireMandatorySplits","Require mandatory splits before finish"],
    ["readerTimestampAuthoritative","Reader timestamp authoritative"],
    ["strictFinalCutoff","Strict final cutoff","Classify a finish recorded after the final deadline as DNF."],
    ["useFirstReadOfPassage","Use first read of passage"],
  ];
  const formatStart=(value:string|null)=>value?new Intl.DateTimeFormat("en-IN",{dateStyle:"medium",timeStyle:"medium",timeZone:"Asia/Kolkata"}).format(new Date(value)):"Not available";
  return <section className="admin-card hub-start-card">
    <div className="admin-card-head"><div><h2>Start Configuration</h2><b>Contest rules</b><p>Configure how official race timing and RFID start detection are handled. Automatic RFID reads never overwrite a locked official start.</p></div></div>
    <div className="hub-contest-scope"><label>Contest<select value={contest?.uuid??contestUuid} onChange={e=>setContestUuid(e.target.value)}>{contests.length?contests.map(item=><option key={item.uuid} value={item.uuid}>{item.name} · Feibot Event UUID: {connection.eventUuid}</option>):connection.contests.map(item=><option key={item.uuid} value={item.uuid}>{item.name} · Feibot Event UUID: {connection.eventUuid}</option>)}</select></label><span><small>Feibot Event UUID</small><b>{connection.eventUuid||"Not connected"}</b></span><span><small>Start window closes</small><b>{formatStart(config.start.startWindowCloseAt)}</b></span></div>
    <div className="hub-start-mode-cards">{(["GUN","WAVE","CHIP"] as const).map(mode=><button type="button" key={mode} className={config.start.timingMode===mode?"active":""} onClick={()=>update({...config,start:{...config.start,timingMode:mode,rankingMethod:mode==="CHIP"?"CHIP":"GUN"}})}><b>{mode} Start</b><small>{modeCopy[mode]}</small></button>)}</div>
    <div className="hub-official-start"><div><small>Official Gun Start</small><strong>{formatStart(displayedGunStart)}</strong><span>Source: {providerGunStart?"Feibot Contest":config.start.gunStartAt?"Saved configuration":"Unavailable"}</span></div><button className="button" disabled={Boolean(busy)} onClick={()=>void refresh()}>{busy==="IMPORT_TIMING_RULES"?<Loader2 className="spin"/>:<RefreshCw/>} Refresh start time from Feibot</button></div>
    <div className="hub-start-dates"><div className="field"><label>Official start override</label><input type="datetime-local" value={local(config.start.gunStartAt)} onChange={e=>update({...config,start:{...config.start,gunStartAt:toIso(e.target.value)}})}/></div><div className="field"><label>Start window closes</label><input type="datetime-local" value={local(config.start.startWindowCloseAt)} onChange={e=>update({...config,start:{...config.start,startWindowCloseAt:toIso(e.target.value)}})}/></div><div className="field"><label>Final deadline</label><input type="datetime-local" value={local(config.start.eventEndAt)} onChange={e=>update({...config,start:{...config.start,eventEndAt:toIso(e.target.value)}})}/></div></div>
    <div className="hub-numeric-rules">{nums.map(([key,label,unit])=><label key={key}><span><b>{label}</b><small>{unit}</small></span><input type="number" min="0" value={config.start[key]} onChange={e=>update({...config,start:{...config.start,[key]:Number(e.target.value)||0}})}/></label>)}</div>
    <div className="platform-toggle-grid compact">{flags.map(([key,label,help])=><label className="platform-toggle-row" key={key}><span><b>{label}</b>{help&&<small>{help}</small>}</span><input type="checkbox" checked={Boolean(config.start[key])} onChange={e=>update({...config,start:{...config.start,[key]:e.target.checked}})}/><i/></label>)}</div>
    <button className="button button-primary hub-full-save" disabled={Boolean(busy)} onClick={()=>void save()}><Save/> Save Start Configuration</button>
  </section>;
}

function FlowPanel({event,connection,dashboard,config,update,save,reload,importRules,splits:allSplits,busy}:{event:HubEvent;connection:FeibotAdminConnection;dashboard:FeibotOperationsDashboard;config:LiveTrackingHubConfig;update:(x:LiveTrackingHubConfig)=>void;save:()=>Promise<void>;reload:()=>Promise<void>;importRules:()=>Promise<unknown>;splits:LiveTrackingHubConfig["splits"];busy:string}) {
  const [contestScope,setContestScope]=useState(allSplits[0]?.providerContestUuid??"");
  const scopes=[...new Set([...dashboard.timingContests.map(c=>c.uuid),...allSplits.map(s=>s.providerContestUuid??"")])];
  const activeScope=scopes.includes(contestScope)?contestScope:(scopes[0]??"");
  const splits=allSplits.filter(s=>(s.providerContestUuid??"")===activeScope).sort((a,b)=>a.order-b.order);
  const issues=raceFlowIssues(config.splits,config.legs,config.timingPoints.map(p=>p.id));
  const saveFlow=async()=>{if(!issues.length)await save();};
  const orderedLegs=useMemo(()=>[...config.legs].sort((a,b)=>a.order-b.order),[config.legs]);
  const [selectedSplitId,setSelectedSplitId]=useState(splits[0]?.id??"");
  const [expandedLegId,setExpandedLegId]=useState(config.legs[0]?.id??"");
  const [draggedSplitId,setDraggedSplitId]=useState<string|null>(null);
  const selectedSplit=splits.find(split=>split.id===selectedSplitId)??splits[0];
  const visibleSplits=splits.filter(split=>split.visible!==false);
  const previewFlow=expandFeibotSportLegs(orderedLegs,visibleSplits);
  const previewCurrentIndex=Math.max(0,visibleSplits.findIndex(split=>split.id===selectedSplit?.id));
  const previewCurrentSplit=visibleSplits[previewCurrentIndex]??visibleSplits[0];
  const selectedContest=dashboard.timingContests.find(c=>c.uuid===activeScope);
  useEffect(()=>{
    const firstSplit=splits[0];
    if(!firstSplit){setSelectedSplitId("");return;}
    if(!splits.some(split=>split.id===selectedSplitId))setSelectedSplitId(firstSplit.id);
  },[selectedSplitId,splits]);
  useEffect(()=>{
    const firstLegWithSplits=orderedLegs.find(leg=>splits.some(split=>split.legId===leg.id))??orderedLegs[0];
    if(firstLegWithSplits&&!orderedLegs.some(leg=>leg.id===expandedLegId))setExpandedLegId(firstLegWithSplits.id);
  },[expandedLegId,orderedLegs,splits]);
  const updateLeg=(id:string,patch:Partial<LiveTrackingHubConfig["legs"][number]>)=>update({...config,legs:config.legs.map(leg=>leg.id===id?{...leg,...patch}:leg)});
  const updateSplit=(id:string,patch:Partial<LiveTrackingHubConfig["splits"][number]>)=>update({...config,splits:normalizeRaceFlowPassages(config.splits.map(split=>split.id===id?{...split,...patch}:split))});
  const arrange=(preferred?:{id:string;legId:string;beforeId?:string})=>{
    if(!preferred || preferred.id===preferred.beforeId)return;
    const draft=splits.map(row=>row.id===preferred.id?{...row,legId:preferred.legId}:row);
    const ids=orderedLegs.flatMap(leg=>{
      const rows=draft.filter(row=>row.legId===leg.id);
      if(leg.id!==preferred.legId)return rows.map(row=>row.id);
      const rest=rows.filter(row=>row.id!==preferred.id).map(row=>row.id);
      const at=preferred.beforeId?rest.indexOf(preferred.beforeId):-1;
      rest.splice(at<0?rest.length:at,0,preferred.id);
      return rest;
    });
    update({...config,splits:reorderContestSplits(config.splits,activeScope,ids,preferred)});
  };
  const autoArrange=()=>{
    const ids=orderedLegs.flatMap(leg=>splits.filter(row=>row.legId===leg.id).sort((a,b)=>(a.distanceKm??Infinity)-(b.distanceKm??Infinity)||a.order-b.order).map(row=>row.id));
    update({...config,splits:reorderContestSplits(config.splits,activeScope,ids)});
  };
  const moveSelected=(offset:number)=>{
    if(!selectedSplit)return;
    const ids=splits.map(row=>row.id),at=ids.indexOf(selectedSplit.id),to=at+offset;
    if(to<0||to>=ids.length)return;
    [ids[at],ids[to]]=[ids[to],ids[at]];
    update({...config,splits:reorderContestSplits(config.splits,activeScope,ids)});
  };
  const addSplit=()=>{if(!orderedLegs[0])return;const next={id:uid("split"),name:`Split ${config.splits.length+1}`,importedName:null,legId:orderedLegs[0].id,order:config.splits.length,distanceKm:null,timingPointId:null,passage:1,cutoffSeconds:null,providerContestUuid:activeScope||null,isFinalRaceSplit:false,visible:true,requiredForProgression:true};update({...config,splits:[...config.splits,next]});setSelectedSplitId(next.id);setExpandedLegId(next.legId);};
  const cutoff=(seconds:number|null|undefined)=>formatCutoffDuration(seconds)||"—";
  return <div className="hub-stack hub-race-flow">
    <section className="admin-card"><h3>Mapping checks</h3><p>Splits follow Feibot order. Customize the athlete-facing name, sport, visibility and sequence; shared-mat passage numbers are handled automatically.</p>{issues.length?<><p role="alert">Fix {issues.length} mapping issue(s) before saving.</p><ul>{issues.map((issue,i)=><li key={i}>{issue}</li>)}</ul></>:<p role="status">Split sequence and mappings pass configuration checks.</p>}
    {splits.filter(row=>!config.legs.some(l=>l.id===row.legId)).map(row=><button type="button" className="button" key={row.id} onClick={()=>setSelectedSplitId(row.id)}>Unassigned: {row.name} — select to repair</button>)}
    </section>
    <div className="hub-flow-layout"><section className="admin-card hub-flow-builder"><div className="admin-card-head"><div><h2>Race Flow Builder</h2><p>Choose a contest → assign each split to a leg and timing mat → order splits → validate and save.</p></div></div>
      <div className="hub-flow-scope"><label>Feibot scope<select value={connection.connectionId??""} disabled><option>{connection.label||connection.eventName||event.name} · {connection.eventUuid||"Not connected"}</option></select></label><small>Event UUID: {connection.eventUuid||"—"}</small><small>Categories: {connection.contests.map(item=>item.name).join(", ")||event.categories.join(", ")||"—"}</small><small>Race date: {connection.raceDate||selectedContest?.raceDate||event.date}</small></div>
      <button className="button" onClick={()=>document.getElementById("race-flow-preview")?.scrollIntoView({behavior:"smooth"})}><Route/> Preview Athlete Timeline</button>
      <div className="hub-flow-steps"><article><b>Step 1 - Select Event</b><p>Choose Event</p><select disabled><option>{event.name}</option></select><span><small>Selected Event</small><strong>{event.name}</strong></span></article><article><b>Step 2 - Select Contest</b><p>Imported legs and splits load automatically.</p><select aria-label="Race flow contest" value={activeScope} onChange={e=>setContestScope(e.target.value)}>{scopes.map(scope=><option key={scope} value={scope}>{dashboard.timingContests.find(c=>c.uuid===scope)?.name||scope||"Legacy event-wide splits"}</option>)}</select><div className="hub-flow-counts"><span><small>Imported Feibot Legs</small><b>{dashboard.rules.legs}</b></span><span><small>Presentation Sport Legs</small><b>{orderedLegs.length}</b></span><span><small>Imported Splits</small><b>{dashboard.rules.splits}</b></span><span><small>Visible Preview Splits</small><b>{visibleSplits.length}</b></span></div></article></div>
      <div className="hub-flow-stage"><div className="admin-card-head"><div><b>Step 3 - Race Flow Builder</b><p>Import splits in Feibot split_index order, then customize their presentation for athletes.</p></div><div className="form-actions"><button className="button" onClick={autoArrange}><Route/> Auto-arrange by KM</button><button className="button" disabled={Boolean(busy)} onClick={()=>void importRules()}><RefreshCw/> Import Feibot rules</button><button className="button" onClick={addSplit}><Plus/> Add split</button></div></div>
        <div className="hub-leg-groups">{orderedLegs.map((leg,legIndex)=>{const legSplits=splits.filter(split=>split.legId===leg.id);const open=expandedLegId===leg.id;return <article key={leg.id} className={open?"open":""} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(draggedSplitId)arrange({id:draggedSplitId,legId:leg.id});setDraggedSplitId(null);}}><button type="button" className="hub-leg-heading" onClick={()=>setExpandedLegId(open?"":leg.id)}>{open?<ChevronDown/>:<ChevronRight/>}<strong className={`sport-${leg.type.toLowerCase()}`}>{leg.type}</strong><span>Leg {legIndex+1}</span><small>{legSplits.length} splits · KM {leg.distanceKm??"—"} · Cutoff Time {cutoff(leg.cutoffSeconds)}</small><b>{legSplits.length}</b></button>{open&&<div className="hub-leg-body"><div className="hub-leg-settings"><label>Leg KM<input type="number" value={leg.distanceKm??""} onChange={e=>updateLeg(leg.id,{distanceKm:e.target.value?Number(e.target.value):null})}/></label><label>Leg cutoff (HH:MM:SS)<CutoffDurationInput value={leg.cutoffSeconds} onChange={cutoffSeconds=>updateLeg(leg.id,{cutoffSeconds})}/><small>Cumulative time from the official start. Leave blank for no leg cutoff.</small></label></div><div className="hub-split-table-head"><span>Imported Split</span><span>Custom Name</span><span>KM / Cutoff Time</span><span>Status</span></div>{legSplits.map(split=><button type="button" draggable key={split.id} className={`hub-split-row ${selectedSplit?.id===split.id?"selected":""}`} onDragStart={e=>{e.dataTransfer.setData("text/plain",split.id);e.dataTransfer.effectAllowed="move";setDraggedSplitId(split.id);}} onDragEnd={()=>setDraggedSplitId(null)} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.stopPropagation();if(draggedSplitId)arrange({id:draggedSplitId,legId:leg.id,beforeId:split.id});setDraggedSplitId(null);}} onClick={()=>setSelectedSplitId(split.id)}><GripVertical/><span><b>{split.importedName||split.name}</b><small>Split Index {split.order+1} · {split.timingPointId||"—"} · {split.distanceKm??0} km</small></span><strong>{split.name}</strong><span><b>{split.distanceKm??0} km</b><small>Cutoff Time: {cutoff(split.cutoffSeconds)}</small></span><em>{split.visible!==false?"Visible":"Hidden"} · {split.requiredForProgression!==false?"Mandatory":"Optional"}</em><i>{leg.type}</i></button>)}</div>}</article>})}</div>
      </div>
    </section>
    <section className="admin-card hub-cutoff-editor"><div className="admin-card-head"><div><h3>Cutoff configuration</h3><p>Add BERGMAN-style cumulative cutoff times. Every value is measured from the official race start.</p></div></div><label>Overall finish cutoff<CutoffDurationInput value={config.start.overallCutoffSeconds} onChange={overallCutoffSeconds=>update({...config,start:{...config.start,overallCutoffSeconds}})}/><small>Maximum event time. Enter HH:MM or HH:MM:SS; leave blank for no overall cutoff.</small></label><div className="hub-split-cutoffs"><div className="hub-split-cutoffs-head"><strong>Split cutoff timings</strong><small>These drive Cutoff Time Volunteer status.</small></div>{[...splits].sort((a,b)=>a.order-b.order).map(split=><label key={split.id}><span><b>{split.name}</b><small>{orderedLegs.find(leg=>leg.id===split.legId)?.type||"OTHER"} · {split.distanceKm??0} km</small></span><CutoffDurationInput value={split.cutoffSeconds} onChange={cutoffSeconds=>updateSplit(split.id,{cutoffSeconds})}/></label>)}</div></section>
    <aside className="admin-card hub-split-editor"><div className="admin-card-head"><div><h3>Logical Split Editor</h3><p>Customize how this race milestone is presented to athletes.</p></div></div>{selectedSplit?<><div className="hub-imported-split"><small>LOGICAL SPLIT</small><b>{selectedSplit.importedName||selectedSplit.name}</b><span>Sequence: {selectedSplit.order+1}</span><span>Physical timing point: {selectedSplit.timingPointId||"—"}</span><span>Passage: {selectedSplit.passage} (automatic)</span><span>Distance: {selectedSplit.distanceKm??0} km</span><span>Cutoff Time: {cutoff(selectedSplit.cutoffSeconds)}</span></div><div className="hub-editor-fields"><label>Assign to Leg<select value={selectedSplit.legId} onChange={e=>{arrange({id:selectedSplit.id,legId:e.target.value});setExpandedLegId(e.target.value);}}>{orderedLegs.map(leg=><option key={leg.id} value={leg.id}>{leg.type}</option>)}</select></label><label>Physical Timing Point<select value={selectedSplit.timingPointId??""} onChange={e=>updateSplit(selectedSplit.id,{timingPointId:e.target.value||null})}><option value="">Not mapped</option>{config.timingPoints.map(point=><option key={point.id} value={point.id}>{point.name} · {point.id}</option>)}</select><small>Shared-mat passage numbers are assigned automatically in race order.</small></label><label>Custom Display Name<input value={selectedSplit.name} onChange={e=>updateSplit(selectedSplit.id,{name:e.target.value})}/><small>Imported Feibot split name remains unchanged.</small></label><div><label>Sequence: {splits.findIndex(s=>s.id===selectedSplit.id)+1}<span><button type="button" className="button" onClick={()=>moveSelected(-1)}>↑ Move earlier</button><button type="button" className="button" onClick={()=>moveSelected(1)}>↓ Move later</button></span></label><label>Visibility<button type="button" className="hub-visibility-button" onClick={()=>updateSplit(selectedSplit.id,{visible:selectedSplit.visible===false})}>{selectedSplit.visible!==false?<><span>Visible</span><Eye/></>:<><span>Hidden</span><EyeOff/></>}</button><small>Hidden checkpoints are removed from public tracking. This does not change course validation.</small></label></div><label className="hub-visible-check"><input type="checkbox" checked={selectedSplit.requiredForProgression!==false} onChange={e=>updateSplit(selectedSplit.id,{requiredForProgression:e.target.checked})}/> Mandatory course/safety checkpoint<small>Independent from visibility. Enable only when a missing read must block official completion.</small>{selectedSplit.visible===false&&selectedSplit.requiredForProgression!==false?<small role="status">This checkpoint will be hidden from public tracking but remains mandatory for official race validation.</small>:null}</label><label className="hub-visible-check"><input type="radio" name={`final-race-split-${selectedSplit.providerContestUuid??"event"}`} checked={selectedSplit.isFinalRaceSplit===true} onChange={()=>update({...config,splits:config.splits.map(split=>({...split,isFinalRaceSplit:(split.providerContestUuid??null)===(selectedSplit.providerContestUuid??null)&&split.id===selectedSplit.id?true:(split.providerContestUuid??null)===(selectedSplit.providerContestUuid??null)?false:split.isFinalRaceSplit}))})}/> Is Final Race Split<small>Only this logical split can mark the athlete FINISHED. The physical mat type does not.</small></label><div><label>Cumulative race KM<input type="number" value={selectedSplit.distanceKm??""} onChange={e=>updateSplit(selectedSplit.id,{distanceKm:e.target.value?Number(e.target.value):null})}/></label><label>Split cutoff (HH:MM:SS)<CutoffDurationInput value={selectedSplit.cutoffSeconds} onChange={cutoffSeconds=>updateSplit(selectedSplit.id,{cutoffSeconds})}/><small>Cumulative time from the official start; blank means no cutoff.</small></label></div></div><div className="hub-editor-actions"><button className="button button-primary" disabled={Boolean(busy)||issues.length>0} onClick={()=>void saveFlow()}><Save/> Save Split</button><button className="button" disabled={Boolean(busy)} onClick={()=>void reload()}><RefreshCw/> Reset</button></div></>:<div className="admin-empty">Import or add a split to begin.</div>}</aside></div>
    <section className="admin-card" id="race-flow-preview"><div className="admin-card-head"><div><h3>Athlete Timeline Preview</h3><p>Updates instantly as you change leg assignment, display order, visibility or custom names.</p></div></div><div className="hub-preview-metrics"><span><small>CURRENT LEG</small><b>{orderedLegs.find(leg=>leg.id===previewCurrentSplit?.legId)?.type||"—"}</b></span><span><small>CURRENT SPLIT</small><b>{previewCurrentSplit?.name||"—"}</b></span><span><small>UPCOMING SPLITS</small><b>{Math.max(0,visibleSplits.length-previewCurrentIndex-1)}</b></span></div><div className="hub-athlete-timeline">{visibleSplits.map((split,index)=>{const state=index<previewCurrentIndex?"completed":index===previewCurrentIndex?"current":"upcoming";return <button type="button" key={split.id} className={state} onClick={()=>setSelectedSplitId(split.id)}>{state==="completed"?<Check/>:state==="current"?<Play/>:<Circle/>}<span><b>{split.name}</b><small>Imported: {split.importedName||split.name} · {split.distanceKm??0} km</small></span><em>{orderedLegs.find(leg=>leg.id===split.legId)?.type||"OTHER"}</em><strong>#{index+1}</strong></button>})}</div></section>
    <div className="hub-flow-previews"><section className="admin-card"><h3>Athlete Modal Preview</h3><p>Preview of the public athlete modal using the current draft race flow.</p><div className="hub-athlete-preview"><header><div><h3>John Smith</h3><span>Bib 102</span></div><b>{orderedLegs.find(leg=>leg.id===previewCurrentSplit?.legId)?.type||"RACE"}</b></header><div className="hub-athlete-current"><span><small>CURRENT LEG</small><b>{orderedLegs.find(leg=>leg.id===previewCurrentSplit?.legId)?.type||"—"}</b></span><span><small>CURRENT SPLIT</small><b>{previewCurrentSplit?.name||"—"}</b></span></div><small>COMPLETED</small>{previewCurrentIndex===0?<div className="hub-empty-completed">No completed splits yet</div>:visibleSplits.slice(0,previewCurrentIndex).map(split=><div className="hub-modal-split completed" key={split.id}><Check/><span><b>{split.name}</b><small>{orderedLegs.find(leg=>leg.id===split.legId)?.type} · {split.distanceKm??0} km</small></span></div>)}<small>CURRENT</small>{previewCurrentSplit&&<div className="hub-modal-split current"><Play/><span><b>{previewCurrentSplit.name}</b><small>{orderedLegs.find(leg=>leg.id===previewCurrentSplit.legId)?.type} · {previewCurrentSplit.distanceKm??0} km</small></span></div>}<small>UPCOMING</small>{visibleSplits.slice(previewCurrentIndex+1).map(split=><div className="hub-modal-split" key={split.id}><Circle/><span><b>{split.name}</b><small>{orderedLegs.find(leg=>leg.id===split.legId)?.type} · {split.distanceKm??0} km</small></span></div>)}</div></section><section className="admin-card"><h3>Race Flow Timeline Preview</h3><p>Visual timeline that mirrors the public split summary flow.</p><div className="hub-race-timeline">{previewFlow.legs.map((leg,index)=>{const rows=previewFlow.splits.filter(split=>split.legId===leg.id);if(!rows.length)return null;const next=previewFlow.legs.slice(index+1).find(candidate=>previewFlow.splits.some(split=>split.legId===candidate.id));const transition=leg.type==="SWIM"&&next?.type==="BIKE"?"T1":leg.type==="BIKE"&&next?.type==="RUN"?"T2":null;const nextStart=previewFlow.splits.find(split=>split.legId===next?.id);return <div key={leg.id}><article><header><Route/><b>{leg.type}</b><span>{rows.length} splits</span></header>{rows.map(split=><div className="hub-race-timeline-split" key={split.id}><b>{split.name}</b><small>Imported: {split.importedName||split.name} · Order {split.order+1} · Visible</small></div>)}</article>{transition&&nextStart&&<div className="hub-transition"><b>{transition} · Auto-calculated transition</b><span>{rows.at(-1)?.name} → {nextStart.name}</span><small>Duration = {rows.at(-1)?.name} time to {nextStart.name} time. Calculated from accepted timing reads.</small></div>}</div>})}</div></section></div>
    <div className="hub-flow-savebar"><button className="button button-primary" disabled={Boolean(busy)||issues.length>0} onClick={()=>void saveFlow()}><Save/> Save Race Flow</button><button className="button" disabled={Boolean(busy)} onClick={()=>void reload()}><RefreshCw/> Reset</button><button className="button" onClick={()=>document.getElementById("race-flow-preview")?.scrollIntoView({behavior:"smooth"})}><Route/> Preview Athlete Timeline</button></div>
  </div>;
}
function PointsPanel({config,update,save,refresh}:{config:LiveTrackingHubConfig;update:(x:LiveTrackingHubConfig)=>void;save:()=>Promise<void>;refresh:()=>Promise<unknown>}){return <section className="admin-card"><div className="admin-card-head"><div><h2>Map Timing Points</h2><p>Independent map-marker metadata; progression is controlled by split mappings.</p></div><div className="form-actions"><button className="button" onClick={()=>void refresh()}><RefreshCw/> Refresh Timing Points</button><button className="button" onClick={()=>update({...config,timingPoints:[...config.timingPoints,{id:uid("tp"),name:`Timing Point ${config.timingPoints.length+1}`,type:"SPLIT",order:config.timingPoints.length,readerUuids:[],course:"SPLIT",km:null,visible:true}]})}><Plus/> Add point</button></div></div><div className="hub-point-cards">{config.timingPoints.map((p,index)=><article key={index}><header><div><strong>{p.name}</strong><small>Provider timing-point ID: {p.id}</small></div><span className="status-pill">{p.visible??true?"Visible":"Hidden"}</span></header><div className="hub-point-fields"><label>Display label<input value={p.name} onChange={e=>update({...config,timingPoints:config.timingPoints.map(x=>x.id===p.id?{...x,name:e.target.value}:x)})}/></label><label>Course<select value={p.course??"SPLIT"} onChange={e=>update({...config,timingPoints:config.timingPoints.map(x=>x.id===p.id?{...x,course:e.target.value as NonNullable<typeof p.course>}:x)})}>{["SWIM","BIKE","RUN","SPLIT","TRANSITION","FINISH"].map(x=><option key={x}>{x}</option>)}</select></label><label>KM position<input type="number" value={p.km??""} onChange={e=>update({...config,timingPoints:config.timingPoints.map(x=>x.id===p.id?{...x,km:e.target.value?Number(e.target.value):null}:x)})}/></label><label>Reader UUIDs<input value={p.readerUuids.join(", ")} onChange={e=>update({...config,timingPoints:config.timingPoints.map(x=>x.id===p.id?{...x,readerUuids:e.target.value.split(",").map(v=>v.trim()).filter(Boolean)}:x)})}/></label><label className="hub-visible-check"><input type="checkbox" checked={p.visible??true} onChange={e=>update({...config,timingPoints:config.timingPoints.map(x=>x.id===p.id?{...x,visible:e.target.checked}:x)})}/> Show on map</label></div></article>)}</div><button className="button button-primary" onClick={()=>void save()}><Save/> Save Timing Point Display</button></section>}
